local CoronationMantleMaker = {}
local PRODUCTS = {
    simple_wool_mantle = { name = "Preprosta volnena mantija", woolCost = 3, silkCost = 1, threadCost = 1, time = 5, cost = 80, prestige = 5, happiness = 2, description = "Preprosta volnena mantija za slovesnosti." },
    silk_ermine_trimmed_mantle = { name = "Svilna hermelinova mantija", silkCost = 3, woolCost = 2, leatherCost = 1, threadCost = 1, time = 8, cost = 240, prestige = 15, happiness = 3, description = "Svilna mantija s hermelinovim obrobom za plemiče." },
    silver_thread_mantle = { name = "Srebrnonitna mantija", silkCost = 3, silverCost = 2, woolCost = 2, leatherCost = 1, threadCost = 1, time = 12, cost = 680, prestige = 28, happiness = 4, description = "Srebrnonitna mantija za visoke plemiče." },
    gold_embroidered_mantle = { name = "Zlato vezana mantija", silkCost = 4, goldCost = 2, silverCost = 1, woolCost = 2, leatherCost = 1, threadCost = 1, time = 16, cost = 1500, prestige = 42, happiness = 6, description = "Zlato vezana mantija za visoko plemstvo." },
    jewel_edged_mantle = { name = "Draguljasta mantija", silkCost = 5, goldCost = 2, silverCost = 1, woolCost = 2, leatherCost = 1, jewelCost = 1, pearlCost = 1, time = 20, cost = 2800, prestige = 55, happiness = 8, description = "Mantija z dragulji za visoko plemstvo." },
    royal_grand_coronation_mantle = { name = "Kraljevski velika kronanska mantija", silkCost = 8, goldCost = 4, silverCost = 2, woolCost = 3, leatherCost = 2, jewelCost = 3, pearlCost = 3, time = 28, cost = 6500, prestige = 80, happiness = 15, description = "Velika kraljevska kronanska mantija z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    mantle_workshop = { name = "Mantijska delavnica", cost = { gold = 280, wood = 120, stone = 100, silk = 6, wool = 6 }, upkeep = 6, qualityBonus = 5 },
    royal_wardrobe = { name = "Kraljevska garderoba", cost = { gold = 1000, wood = 280, stone = 280, silver = 8, leather = 6 }, upkeep = 24, qualityBonus = 18 },
    master_ceremonial_atelier = { name = "Mojstrski slovesnostni atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_coronation_palace = { name = "Kraljevska kronanska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 20 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
CoronationMantleMaker.silkStock = 14; CoronationMantleMaker.woolStock = 14; CoronationMantleMaker.leatherStock = 10; CoronationMantleMaker.threadStock = 12; CoronationMantleMaker.silverStock = 6; CoronationMantleMaker.goldStock = 6; CoronationMantleMaker.jewelStock = 4; CoronationMantleMaker.pearlStock = 4
CoronationMantleMaker.productStock = {}; CoronationMantleMaker.buildings = {}; CoronationMantleMaker.maker = nil; CoronationMantleMaker.activeMaking = {}; CoronationMantleMaker.totalProducts = 0; CoronationMantleMaker.dayTimer = 0
function CoronationMantleMaker.init() CoronationMantleMaker.silkStock=14; CoronationMantleMaker.woolStock=14; CoronationMantleMaker.leatherStock=10; CoronationMantleMaker.threadStock=12; CoronationMantleMaker.silverStock=6; CoronationMantleMaker.goldStock=6; CoronationMantleMaker.jewelStock=4; CoronationMantleMaker.pearlStock=4; CoronationMantleMaker.productStock={}; CoronationMantleMaker.buildings={}; CoronationMantleMaker.maker=nil; CoronationMantleMaker.activeMaking={}; CoronationMantleMaker.totalProducts=0; CoronationMantleMaker.dayTimer=0; print("[CoronationMantleMaker] Royal Coronation Mantle Maker System initialized (6 products, 4 buildings)") end
function CoronationMantleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoronationMantleMaker.maker={name=n or ("Mantijar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mantijar najet: %s (spretnost: %d)",CoronationMantleMaker.maker.name,s),"success") end; return true end
function CoronationMantleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoronationMantleMaker.build(id) local ok,e=CoronationMantleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoronationMantleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoronationMantleMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoronationMantleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoronationMantleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and CoronationMantleMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.woolCost and CoronationMantleMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.leatherCost and CoronationMantleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.threadCost and CoronationMantleMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silverCost and CoronationMantleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoronationMantleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoronationMantleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoronationMantleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoronationMantleMaker.buildings==0 then return false,"Potrebna mantijska delavnica" end; if not CoronationMantleMaker.maker then return false,"Potreben mantijar" end; return true end
function CoronationMantleMaker.make(pt,qty) qty=qty or 1; local ok,e=CoronationMantleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then CoronationMantleMaker.silkStock=CoronationMantleMaker.silkStock-d.silkCost*qty end; if d.woolCost then CoronationMantleMaker.woolStock=CoronationMantleMaker.woolStock-d.woolCost*qty end; if d.leatherCost then CoronationMantleMaker.leatherStock=CoronationMantleMaker.leatherStock-d.leatherCost*qty end; if d.threadCost then CoronationMantleMaker.threadStock=CoronationMantleMaker.threadStock-d.threadCost*qty end; if d.silverCost then CoronationMantleMaker.silverStock=CoronationMantleMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoronationMantleMaker.goldStock=CoronationMantleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoronationMantleMaker.jewelStock=CoronationMantleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoronationMantleMaker.pearlStock=CoronationMantleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoronationMantleMaker.maker then t=math.max(1,t-math.floor(CoronationMantleMaker.maker.skill/12)) end; table.insert(CoronationMantleMaker.activeMaking,{id="mantle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šivanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoronationMantleMaker.completeMaking(m) local q=1.0+(CoronationMantleMaker.getQualityBonus()/100); if CoronationMantleMaker.maker then q=q+(CoronationMantleMaker.maker.skill/140) end; q=math.min(2.5,q); CoronationMantleMaker.productStock[m.productType]=(CoronationMantleMaker.productStock[m.productType] or 0)+m.quantity; CoronationMantleMaker.totalProducts=CoronationMantleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoronationMantleMaker.maker then CoronationMantleMaker.maker.itemsMade=CoronationMantleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoronationMantleMaker.maker.skill=math.min(100,CoronationMantleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mantija izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coronationmantle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoronationMantleMaker.update(dt) if not _G.state then return end; CoronationMantleMaker.dayTimer=CoronationMantleMaker.dayTimer+dt; if CoronationMantleMaker.dayTimer>=30 then CoronationMantleMaker.dayTimer=0; for i=#CoronationMantleMaker.activeMaking,1,-1 do local m=CoronationMantleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoronationMantleMaker.completeMaking(m); table.remove(CoronationMantleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoronationMantleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoronationMantleMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoronationMantleMaker.getStats() return {silkStock=CoronationMantleMaker.silkStock,woolStock=CoronationMantleMaker.woolStock,leatherStock=CoronationMantleMaker.leatherStock,threadStock=CoronationMantleMaker.threadStock,silverStock=CoronationMantleMaker.silverStock,goldStock=CoronationMantleMaker.goldStock,jewelStock=CoronationMantleMaker.jewelStock,pearlStock=CoronationMantleMaker.pearlStock,productStock=CoronationMantleMaker.productStock,numBuildings=#CoronationMantleMaker.buildings,hasMaker=CoronationMantleMaker.maker~=nil,makerName=CoronationMantleMaker.maker and CoronationMantleMaker.maker.name or "—",makerSkill=CoronationMantleMaker.maker and CoronationMantleMaker.maker.skill or 0,activeMaking=#CoronationMantleMaker.activeMaking,totalProducts=CoronationMantleMaker.totalProducts} end
return CoronationMantleMaker
